function lgbmPredict(vec) {
  let score = 0;
  for (const t of LGBM_TREES) {
    let node = t.r;
    while (node >= 0) {
      const [fi, thr] = t.s[node];
      const [l, r] = t.c[node];
      node = vec[fi] <= thr ? l : r;
    }
    score += t.l[-(node + 1)];
  }
  return 1 / (1 + Math.exp(-score));
}

function buildVec(labelsFlat) {
  const featIdx = Object.create(null);
  for (let i = 0; i < LGBM_FEATURES.length; i++) featIdx[LGBM_FEATURES[i]] = i;

  const vec = new Float32Array(LGBM_FEATURES.length);

  for (const [key, val] of Object.entries(labelsFlat)) {
    if (typeof val !== 'number') continue;
    if (key.startsWith('adult__')) {
      // V6 new counter-tags: already in "adult__XXX" format → use directly
      if (key in featIdx) vec[featIdx[key]] = val;
    } else if (key.startsWith('adult_')) {
      // Old-style single-underscore adult tags: "adult_XXX" → "adult__XXX"
      const fname = 'adult__' + key.slice(6);
      if (fname in featIdx) vec[featIdx[fname]] = val;
    } else if (key.startsWith('underage_')) {
      // Underage tags: strip "underage_" prefix → bare name
      const fname = key.slice(9);
      if (fname in featIdx) vec[featIdx[fname]] = val;
    }
  }
  return vec;
}

function combineScores(labelsFlat) {
  // Extract top-level probability scores from the flat labels object
  const minor    = labelsFlat.minor    ?? 0;  // P(any minor in image)
  const adult    = labelsFlat.adult    ?? 0;  // P(adult)
  const underage = labelsFlat.underage ?? 0;  // P(underage / child or teen)

  // Ratio block: high underage confidence + any minor signal, or very strong minor alone
  const ratioBlocked = (underage >= 0.72 && minor >= 0.035) || minor >= 0.70;

  const vec = buildVec(labelsFlat);
  const lgbmScore = lgbmPredict(vec);
  const lgbmBlocked = lgbmScore >= 0.80;

  return { minor, adult, underage, lgbmScore, lgbmBlocked, ratioBlocked };
}

export async function run({ inputs }) {
  // inputs.labels is the flat labels object from the siglip2 underage node
  const labelsFlat = inputs.labels ?? {};

  const { minor, adult, underage, lgbmScore, lgbmBlocked, ratioBlocked } = combineScores(labelsFlat);
  const blocked = lgbmBlocked || ratioBlocked;

  return NextNode.from({
    outputs: {
      labels:  blocked ? ['underage'] : [],
      details: {
        lgbm_score:    lgbmScore,
        lgbm_blocked:  lgbmBlocked,
        ratio_blocked: ratioBlocked,
        minor_risk:    minor,
        adult_conf:    adult,
        underage_conf: underage,
        version:       'v6',
      },
    },
  });
}
